            <feOffset dx=".2" dy=".3"/>
            <feMerge>
              <feMergeNode/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
          <filter id="dropShadow05" name="Shadow 0.5">
            <feGaussianBlur in="SourceAlpha" stdDeviation=".5"/>
            <feOffset dx=".5" dy=".7"/>
            <feMerge>
              <feMergeNode/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
          <filter id="outline" name="Outline">
